import test from 'node:test';
import assert from 'node:assert';
import { createState, collides } from '../game/neon.js';

test('D3: Ball should not stick to brick (naive vy-flip fails)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball deeply inside the brick
  state.ball.x = brick.x + 10;
  state.ball.y = brick.y + 10; 
  state.ball.vy = -260;

  // Simulation of a bounce (naive: just flip vy)
  if (collides(state.ball, brick)) {
    state.ball.vy = -state.ball.vy;
  }

  // After a bounce, the ball should not be still colliding if we are talking about resolution
  // But wait, the naive fix only flips vy. The ball is still at y=10.
  // The invariant is: After resolution, the ball is outside the rectangle.
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should be pushed out of the brick');
});

import test from 'node:test';
import assert from 'node:assert';
import { createState, collides } from '../game/neon.js';

test('D4: Ball should not suffer double inversion at seams', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1]; // Next to brick1

  // Position ball to collide with BOTH bricks
  // brick1.x = offsetX, brick1.w = 72
  // brick2.x = offsetX + 72 + 8 = offsetX + 80
  // Ball radius = 7. If ball.x is at offsetX + 76, it overlaps both.
  state.ball.x = brick1.x + brick1.w - 2; 
  state.ball.y = brick1.y + 10;
  state.ball.vy = -260;

  // Simulation of naive frame loop:
  for (const brick of state.bricks) {
    if (collides(state.ball, brick)) {
      state.ball.vy = -state.ball.vy;
    }
  }

  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced ONCE, not twice');
});

