import test from 'node:test';
import assert from 'node:assert';
import { createState, collides } from '../game/neon.js';

test('D5: Ball should bounce on both axes when hitting a corner', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball at the bottom-right corner of the brick
  // brick: x, y, w=72, h=20
  state.ball.x = brick.x + brick.w + 2; // slightly to the right
  state.ball.y = brick.y + brick.h + 2; // slightly below
  state.ball.vx = -260;
  state.ball.vy = -260;

  // Shift slightly so it collides
  state.ball.x = brick.x + brick.w - 2;
  state.ball.y = brick.y + brick.h - 2;

  // Naive correction: flip only the axis with most penetration?
  // Or just flip vy if it's a brick?
  // Let's see what the current "no bounce" does: it does nothing.
  // A naive fix would be: if (collides) { ball.vy = -ball.vy; }

  // For the test, we want to ensure THAT IF it bounces, it bounces BOTH ways.
  // Since we have no bounce yet, this will fail.

  // I'll implement the "naive fix" in the test to show it fails if it only flips one axis.
  if (collides(state.ball, brick)) {
    state.ball.vy = -state.ball.vy; // Naive flip
  }

  assert.strictEqual(state.ball.vx > 0, true, 'Ball vx should have flipped');
  assert.strictEqual(state.ball.vy > 0, true, 'Ball vy should have flipped');
});

